"use strict";document.addEventListener("DOMContentLoaded",function(){var q=document.getElementById("q");if(!q)return;var cards=Array.from(document.querySelectorAll("[data-search]"));var sels={year:document.getElementById("fYear"),version:document.getElementById("fVersion"),category:document.getElementById("fCategory"),status:document.getElementById("fStatus"),component:document.getElementById("fComponent")};var count=document.getElementById("resultCount");function norm(s){return(s||"").toLowerCase()}function apply(){var term=norm(q.value);var n=0;cards.forEach(function(c){var d=c.dataset;var ok=true;if(sels.year&&sels.year.value&&d.year!==sels.year.value)ok=false;if(ok&&sels.version&&sels.version.value&&d.version!==sels.version.value)ok=false;if(ok&&sels.category&&sels.category.value&&d.category!==sels.category.value)ok=false;if(ok&&sels.status&&sels.status.value&&d.status!==sels.status.value)ok=false;if(ok&&sels.component&&sels.component.value&&(d.components||"").split(" ").indexOf(sels.component.value)<0)ok=false;if(ok&&term&&norm(d.search).indexOf(term)<0)ok=false;c.hidden=!ok;if(ok)n++});if(count){var isEn=document.documentElement.lang==="en"||!document.documentElement.lang;count.textContent=isEn?(n+" of "+cards.length+" changes displayed."):(n+" dari "+cards.length+" perubahan ditampilkan.");}}["change","input"].forEach(function(ev){q.addEventListener(ev,apply)});Object.keys(sels).forEach(function(k){if(sels[k])sels[k].addEventListener("change",apply)});apply();});